from html.parser import HTMLParser
from pathlib import Path
import subprocess, tempfile, os, sys
files=['dang-tin-tuyen-dung.html','dang-tin-viec-lam.html','nha-tuyen-dung.html','quan-ly-tin-tuyen-dung.html']
class Parser(HTMLParser):
    def __init__(self):
        super().__init__(); self.in_script=False; self.script_attrs=None; self.scripts=[]; self.ids={}; self.forms=[]; self.inputs=[]
    def handle_starttag(self, tag, attrs):
        ad=dict(attrs)
        if 'id' in ad: self.ids[ad['id']]=self.ids.get(ad['id'],0)+1
        if tag=='form': self.forms.append(ad)
        if tag in ('input','select','textarea','button'): self.inputs.append((tag,ad))
        if tag=='script': self.in_script=True; self.script_attrs=ad; self._buf=[]
    def handle_endtag(self, tag):
        if tag=='script' and self.in_script:
            self.scripts.append((self.script_attrs,''.join(self._buf))); self.in_script=False
    def handle_data(self, data):
        if self.in_script: self._buf.append(data)
errors=0
for f in files:
    parser=Parser(); parser.feed(Path(f).read_text(encoding='utf-8',errors='replace'))
    dup={k:v for k,v in parser.ids.items() if v>1}
    unnamed=[(tag,ad.get('id','')) for tag,ad in parser.inputs if tag != 'button' and ad.get('type') not in ('hidden',) and not ad.get('name')]
    print(f'## {f}: duplicate_ids={dup or "none"} forms={len(parser.forms)} unnamed_visible_fields={unnamed[:8]}')
    for idx,(attrs,code) in enumerate(parser.scripts,1):
