            print(('JS_OK' if cp.returncode==0 else 'JS_FAIL'), f, f'script#{idx}')
            if cp.returncode:
                errors+=1; print(cp.stderr.strip() or cp.stdout.strip())
        finally: os.unlink(name)
if errors: sys.exit(1)
